test({ sr: 'isti argumenti: fn se poziva jednom', en: 'same arguments: fn is called once' }, () => {
  let calls = 0;
  const f = memoize((a, b) => { calls++; return a + b; });
  expect(f(1, 2)).toBe(3);
  expect(f(1, 2)).toBe(3);
  expect(calls).toBe(1);
});
test({ sr: 'različiti argumenti se računaju posebno', en: 'different arguments are computed separately' }, () => {
  let calls = 0;
  const f = memoize((n) => { calls++; return n * 2; });
  f(1); f(2); f(1);
  expect(calls).toBe(2);
});

