test('caches undefined results too', () => {
  let calls = 0;
  const f = memoize(() => { calls++; return undefined; });
  f(); f();
  expect(calls).toBe(1);
});
test('each memoized function has its own cache', () => {
  let a = 0;
  let b = 0;
  const fa = memoize((n) => { a++; return n; });
  const fb = memoize((n) => { b++; return n; });
  fa(1); fb(1);
  expect(a).toBe(1);
  expect(b).toBe(1);
});

